function memberHtml(){if(state.pageId==='member'){const info=state.stateId==='member'?['会员有效','你的会员权益正在生效','可使用专属功能与会员服务。','管理会员','manage']:state.stateId==='expired'?['会员已过期','续费后继续使用会员权益','过期后，部分会员功能将不可用。','立即续费','join']:['当前为非会员','解锁更多专属权益','开通后可体验完整会员服务。','立即开通','join'];const cta=state.platform==='ios'&&info[4]==='join'?'联系客服':info[3];return `<div class="mobile-title"><h1>会员中心</h1><i class="avatar"></i></div><section class="member-card"><span class="tag">${info[0]}</span><h2>${info[1]}</h2><p>${info[2]}</p><button class="phone-action" data-target="${info[4]}">${cta}</button></section><div class="section-title"><b>会员权益</b><span>查看全部 ›</span></div><div class="list">${['权益一','权益二'].map(t=>`<button class="list-row" data-target="manage"><i class="fake-icon"></i><span><b>${t}</b><small>会员可使用的通用能力</small></span><em class="arrow">›</em></button>`).join('')}</div><div class="section-title" style="margin-top:22px"><b>当前状态</b></div><section class="app-hero"><small>切换示例</small><h2>${pageState().name}</h2><p>使用设备上方状态切换，查看不同界面和不同规则。</p></section>`}}
